Begin AV_RolasaFatherS

short nolore

if ( getjournalindex "AV_Rolasa_Deleth" < 10 )
	disable
	return
endif

if ( getjournalindex "AV_Rolasa_Deleth" >= 10 )
	if ( getjournalindex "AV_Rolasa_Deleth" < 19 )
		enable
	endif
endif


if ( getjournalindex "AV_Rolasa_Deleth" >= 19 )
	if ( GetDisabled == 0 )
		if ( CellChanged == 1 )
			disable
		endif
	endif
endif

End AV_RolasaFatherS

Begin cybLichFight

short doonce

if ( doonce == 0 )
	if ( getdistance, player < 400 )
		if ( GetDetected, Player == 1 )
			if ( player->getinvisible == 0 )
				addspell "cybLichSummonAV"
				placeatpc "AV_LichPGhost" 1,128,1
				set doonce to 1
			endif
		endif
	endif
endif

if ( getdistance, player <= 250 )
	if ( getspell "cybLichShieldAV" == 0 )
		addspell "cybLichShieldAV"
	endif
endif

End cybLichFight

